import citiesAsset from '../assets/geo/cn-cities.json'
import provincesAsset from '../assets/geo/cn-provinces.json'
import type { ServerView } from './types'

/**
 * Offline geography for the vendor catalog.
 *
 * Both assets are generated by `scripts/geo/build-cn-geo.mjs` from DataV
 * GeoAtlas and committed, so the dashboard never contacts a map service: the
 * province paths are already projected into the asset's viewBox and the city
 * points are pre-projected into the same space.
 */

export const UNKNOWN_PROVINCE = '00'
export const PROVINCE_VIEWBOX: string = provincesAsset.viewBox

export interface ProvinceShape {
  code: string
  name: string
  shortName: string
  nameEn: string
  path: string
  centroid: [number, number]
  bbox: [number, number, number, number]
}

export interface CityPoint {
  code: string
  name: string
  provinceCode: string
  x: number
  y: number
  aliases?: string[]
}

export const PROVINCES: readonly ProvinceShape[] = provincesAsset.provinces as ProvinceShape[]

const CITY_POINTS: readonly CityPoint[] = citiesAsset.cities as CityPoint[]

const CITY_BY_NAME = new Map<string, CityPoint>()
for (const city of CITY_POINTS) {
  CITY_BY_NAME.set(city.name, city)
  for (const alias of city.aliases ?? []) CITY_BY_NAME.set(alias, city)
}

/**
 * Vendor titles are `<city> #<n>`; the city part is the only geography the
 * live payload carries (`ServerView` has no `loc[]`). Titles were verified to
 * always end in `#<digits>`, but the parser is defensive: a title without the
 * suffix is used whole.
 */
export function parseServerTitle(title: string): string {
  return title.replace(/#\s*\d+\s*$/, '').trim()
}

const cityCache = new Map<string, CityPoint | null>()

/**
 * Exact match first, then the one-directional prefix rule the geo research
 * validated (`feature_name.startswith(base)`): `延边朝鲜族自治州` starts with
 * `延边`, while `宿州` never matches `宿迁`. An ambiguous prefix resolves to
 * nothing rather than guessing. Aliases (`济南 - 莱芜`, `延吉`) are exact keys.
 */
export function resolveServerCity(title: string): CityPoint | null {
  const base = parseServerTitle(title)
  if (!base) return null
  if (cityCache.has(base)) return cityCache.get(base) ?? null
  let hit = CITY_BY_NAME.get(base) ?? null
  if (!hit) {
    const matches = CITY_POINTS.filter((city) => city.name.startsWith(base))
    if (matches.length === 1) hit = matches[0]
  }
  cityCache.set(base, hit)
  return hit
}

export function provinceCodeForTitle(title: string): string {
  return resolveServerCity(title)?.provinceCode ?? UNKNOWN_PROVINCE
}

export interface ProvinceDatum {
  code: string
  name: string
  nameEn: string
  count: number
  /** Distinct vendor city labels that resolved inside this province. */
  cities: number
  connected: number
  current: boolean
  shape: ProvinceShape
}

export interface CatalogGeoSummary {
  /** All 31 mainland provinces, including zero-count ones. */
  provinces: ProvinceDatum[]
  /** Servers whose title does not resolve to a province. */
  unknown: number
  total: number
  current: ServerView | null
  currentCity: CityPoint | null
  currentProvince: string | null
}

interface ProvinceAccumulator {
  count: number
  cities: Set<string>
  connected: number
}

/**
 * Groups catalog rows by province. The current row is the first `LIVE` node;
 * `connected` counts LIVE or DRAINING nodes (a claim from the runtime, not a
 * probe). Nothing is invented: an unresolved title lands in `unknown`.
 */
export function summarizeCatalogGeo(rows: readonly ServerView[]): CatalogGeoSummary {
  const accumulators = new Map<string, ProvinceAccumulator>()
  let unknown = 0
  let current: ServerView | null = null
  let currentCity: CityPoint | null = null

  for (const row of rows) {
    const city = resolveServerCity(row.title)
    const code = city?.provinceCode ?? UNKNOWN_PROVINCE
    if (code === UNKNOWN_PROVINCE) {
      unknown += 1
    } else {
      let bucket = accumulators.get(code)
      if (!bucket) {
        bucket = { count: 0, cities: new Set(), connected: 0 }
        accumulators.set(code, bucket)
      }
      bucket.count += 1
      if (city) bucket.cities.add(city.code)
      if (row.nodeState === 'LIVE' || row.nodeState === 'DRAINING') bucket.connected += 1
    }
    if (!current && row.nodeState === 'LIVE') {
      current = row
      currentCity = city
    }
  }

  const currentProvince = currentCity?.provinceCode ?? null
  return {
    provinces: PROVINCES.map((shape) => {
      const bucket = accumulators.get(shape.code)
      return {
        code: shape.code,
        name: shape.shortName,
        nameEn: shape.nameEn,
        count: bucket?.count ?? 0,
        cities: bucket?.cities.size ?? 0,
        connected: bucket?.connected ?? 0,
        current: shape.code === currentProvince,
        shape,
      }
    }),
    unknown,
    total: rows.length,
    current,
    currentCity,
    currentProvince,
  }
}

/** Fixed choropleth bins, so filtered counts stay comparable. */
export function fillBin(count: number): 0 | 1 | 2 | 3 | 4 | 5 {
  if (count <= 0) return 0
  if (count <= 20) return 1
  if (count <= 50) return 2
  if (count <= 150) return 3
  if (count <= 300) return 4
  return 5
}
